            entry%interactive = .true.
            entry%doc = "Go to the previous COUNT'th hunk."//LF// &
                        "Interactively, COUNT is the prefix numeric argument, and defaults"//LF// &
                        "to 1."
        case ("diff_kill_junk")
            entry%file = "diff_mode_fm.f90"
            entry%interactive = .true.
