            entry%original = "VC_DISPLAY_STATUS_T"

            select case (vc_display_status)
            case (VC_DISPLAY_STATUS_NIL)
                entry%value = "VC_DISPLAY_STATUS_NIL"
            case (VC_DISPLAY_STATUS_T)
                entry%value = "VC_DISPLAY_STATUS_T"
            case (VC_DISPLAY_STATUS_NO_BACKEND)
                entry%value = "VC_DISPLAY_STATUS_NO_BACKEND"
            case default
                entry%value = repr(vc_display_status)
            end select

            entry%doc = "If true, display revision number and lock status in mode line."//LF// &
                        "If false, only the backend name is displayed.  When the value"//LF// &
                        "is VC_DISPLAY_STATUS_NO_BACKEND, then no backend name is displayed before the"//LF// &
                        "revision number and lock status."
        case ("vc_find_revision_no_save")
            entry%file = "vc_fm.f90"
            entry%fortran = "vc_find_revision_no_save"
            entry%user_option = .true.
            entry%original = ".false."
            entry%value = repr(vc_find_revision_no_save)
            entry%doc = "If true, `vc_find_revision' doesn't write the created buffer to file."
        case ("vc_finish_logentry_hook")
            entry%file = "vc_dispatcher_fm.f90"
            entry%fortran = "vc_finish_logentry_hook"
            entry%doc = "Hook run at the end of `vc_finish_logentry' (obsolete; use"//LF// &
                        "`vc_log_after_operation_hook')."
        case ("vc_follow_symlinks")
            entry%file = "vc_hooks_fm.f90"
            entry%fortran = "vc_follow_symlinks"
            entry%user_option = .true.
            entry%original = "VC_FOLLOW_SYMLINKS_ASK"

            select case (vc_follow_symlinks)
            case (VC_FOLLOW_SYMLINKS_NIL)
                entry%value = "VC_FOLLOW_SYMLINKS_NIL"
            case (VC_FOLLOW_SYMLINKS_T)
                entry%value = "VC_FOLLOW_SYMLINKS_T"
            case (VC_FOLLOW_SYMLINKS_ASK)
                entry%value = "VC_FOLLOW_SYMLINKS_ASK"
            case default
                entry%value = repr(vc_follow_symlinks)
            end select

            entry%doc = "What to do if visiting a symbolic link to a file under version control."//LF// &
                        "Editing such a file through the link bypasses the version control system,"//LF// &
                        "which is dangerous and probably not what you want."//LF// &
                        ""//LF// &
                        "If this variable is VC_FOLLOW_SYMLINKS_T, VC follows the link and visits the real file,"//LF// &
                        "telling you about it in the echo area.  If it is VC_FOLLOW_SYMLINKS_ASK, VC asks for"//LF// &
                        "confirmation whether it should follow the link.  If VC_FOLLOW_SYMLINKS_NIL, the link is"//LF// &
                        "visited and a warning displayed."
        case ("vc_git_diff_switches")
            entry%file = "vc_git_fm.f90"
            entry%fortran = "vc_git_diff_switches"
            entry%user_option = .true.
            entry%doc = "String or list of strings specifying switches for Git diff under VC."//LF// &
                        "If nil, use the value of `vc_diff_switches'.  If t, use no switches."
        case ("vc_git_log_edit_mode_map")
            entry%file = "vc_git_fm.f90"
            entry%fortran = "vc_git_log_edit_mode_map"
            entry%doc = "Keymap of `vc_git_log_edit_mode'."
        case ("vc_git_log_edit_summary_max_len")
            entry%file = "vc_git_fm.f90"
            entry%fortran = "vc_git_log_edit_summary_max_len"
            entry%original = "68"
            entry%value = repr(vc_git_log_edit_summary_max_len)
            entry%doc = "Maximum length for Git commit summary lines."//LF// &
                        "If a number, characters in summary lines beyond this length are"//LF// &
                        "displayed in the `vc_git_log_edit_summary_max_warning' face."//LF// &
                        "A negative value means no highlighting."//LF// &
                        ""//LF// &
                        "It is good practice to avoid writing summary lines longer than"//LF// &
                        "this because otherwise the summary line will be truncated in many"//LF// &
                        "contexts in which Git commands display summary lines."//LF// &
                        ""//LF// &
                        "See also `vc_git_log_edit_summary_target_len'."
        case ("vc_git_log_edit_summary_max_warning")
            entry%file = "vc_git_fm.f90"
            entry%fortran = "vc_git_log_edit_summary_max_warning"
            entry%doc = "Face for Git commit summary lines beyond the maximum length."//LF// &
                        "See `vc_git_log_edit_summary_max_len'."
        case ("vc_git_log_edit_summary_target_len")
            entry%file = "vc_git_fm.f90"
            entry%fortran = "vc_git_log_edit_summary_target_len"
            entry%original = "-1"
            entry%value = repr(vc_git_log_edit_summary_target_len)
            entry%doc = "Target length for Git commit summary lines."//LF// &
                        "If a number, characters in Summary: lines beyond this length are"//LF// &
                        "displayed in the `vc_git_log_edit_summary_target_warning' face."//LF// &
                        "A negative value means no highlighting."//LF// &
                        ""//LF// &
                        "By setting this to an integer around 50, you can improve the"//LF// &
                        "compatibility of your commit messages with Git commands that"//LF// &
                        "print the summary line in width-constrained contexts.  However,"//LF// &
                        "many commit summaries will need to exceed this length."//LF// &
                        ""//LF// &
                        "See also `vc_git_log_edit_summary_max_len'."
        case ("vc_git_log_edit_summary_target_warning")
            entry%file = "vc_git_fm.f90"
            entry%fortran = "vc_git_log_edit_summary_target_warning"
            entry%doc = "Face for Git commit summary lines beyond the target length."//LF// &
                        "See `vc_git_log_edit_summary_target_len'."
        case ("vc_git_log_switches")
            entry%file = "vc_git_fm.f90"
            entry%fortran = "vc_git_log_switches"
            entry%doc = "String or list of strings giving Git log switches for non-shortlogs."
        case ("vc_git_print_log_follow")
            entry%file = "vc_git_fm.f90"
            entry%fortran = "vc_git_print_log_follow"
            entry%original = ".false."
            entry%value = repr(vc_git_print_log_follow)
            entry%doc = "If true, use the flag `--follow' when producing single file logs."//LF// &
                        ""//LF// &
                        "A true value will make the printed log automatically follow"//LF// &
                        "the file renames.  The downsides is that the log produced this"//LF// &
                        "way may omit certain (merge) commits, and that `log_view_diff'"//LF// &
                        "fails on commits that used the previous name, in that log buffer."//LF// &
                        ""//LF// &
                        "When this variable is false, and the log ends with a rename, there is a"//LF// &
                        "button which you can press to show the log for the file name before the"//LF// &
                        "rename."
        case ("vc_git_program")
            entry%file = "vc_git_fm.f90"
            entry%fortran = "vc_git_program"
            entry%user_option = .true.

            if (allocated(vc_git_program)) then
                entry%value = repr(vc_git_program)
            else
                entry%value = "unallocated"
            end if

            entry%doc = "Name of the Git executable (excluding any arguments)."
        case ("vc_git_revision_complete_only_branches")
            entry%file = "vc_git_fm.f90"
            entry%fortran = "vc_git_revision_complete_only_branches"
            entry%user_option = .true.
            entry%original = ".false."
            entry%value = repr(vc_git_revision_complete_only_branches)
            entry%doc = "Control whether tags are returned by revision completion for Git."//LF// &
                        ""//LF// &
                        "When true, only branches and remotes will be returned by"//LF// &
                        "`vc_git_revision_completion_table'.  This is used by various VC"//LF// &
                        "commands when completing branch names.  When false, tags are also"//LF// &
                        "included in the completions."
        case ("vc_git_root_log_format")
            entry%file = "vc_git_fm.f90"
            entry%fortran = "vc_git_root_log_format"
            entry%doc = "Git log format for `vc_print_root_log'."//LF// &
                        "This should be a FORMAT, a REGEXP and KEYWORDS, where FORMAT is a"//LF// &
                        "format string (which is passed to ""git log"" via the argument"//LF// &
                        """--pretty=tformat:FORMAT""), REGEXP is a regular expression"//LF// &
                        "matching the resulting Git log output, and KEYWORDS is a list of"//LF// &
                        "`font_lock_keywords' for highlighting the Log View buffer."
        case ("vc_git_shortlog_switches")
            entry%file = "vc_git_fm.f90"
            entry%fortran = "vc_git_shortlog_switches"
            entry%doc = "String or list of strings giving Git log switches for shortlogs."
        case ("vc_git_use_literal_pathspecs")
            entry%file = "vc_git_fm.f90"
            entry%fortran = "vc_git_use_literal_pathspecs"
            entry%original = ".true."
            entry%value = repr(vc_git_use_literal_pathspecs)
            entry%doc = "True to treat pathspecs in commands literally."//LF// &
                        "Good example of file name that needs this: ""test[56].xx""."
        case ("vc_handled_backends")
            entry%file = "vc_hooks_fm.f90"
            entry%fortran = "vc_handled_backends"
            entry%user_option = .true.

            if (allocated(vc_handled_backends)) then
                entry%value = repr(vc_handled_backends)
            else
                entry%value = "unallocated"
            end if

            entry%doc = "List of version control backends for which VC will be used."//LF// &
                        "Entries in this list will be tried in order to determine whether a"//LF// &
                        "file is under that sort of version control."//LF// &
                        "Removing an entry from the list prevents VC from being activated"//LF// &
                        "when visiting a file managed by that backend."//LF// &
                        "An empty list disables VC altogether."
        case ("vc_ignore_dir_regexp")
            entry%file = "vc_hooks_fm.f90"
            entry%fortran = "vc_ignore_dir_regexp"
            entry%user_option = .true.

            if (allocated(vc_ignore_dir_regexp)) then
                entry%value = repr(vc_ignore_dir_regexp)
            else
                entry%value = "unallocated"
            end if

            entry%doc = "Regexp matching directory names that are not under VC's control."//LF// &
                        "The default regexp prevents fruitless and time-consuming attempts"//LF// &
                        "to determine the VC status in directories in which filenames are"//LF// &
                        "interpreted as hostnames."
        case ("vc_log_finish_functions")
            entry%file = "vc_fm.f90"
            entry%fortran = "vc_log_finish_functions"
            entry%doc = "Functions run at the end of the log command."//LF// &
                        "Each function runs in the log output buffer without args."
        case ("vc_log_short_style")
            entry%file = "vc_fm.f90"
            entry%fortran = "vc_log_short_style"
            entry%doc = "Whether or not to show a short log."//LF// &
                        "If `directory' is true, show a short log if the fileset"//LF// &
                        "contains a directory."//LF// &
                        "If `file' is true, show short logs for files."//LF// &
                        "Not all VC backends support short logs!"
        case ("vc_log_show_limit")
            entry%file = "vc_fm.f90"
            entry%fortran = "vc_log_show_limit"
            entry%user_option = .true.
            entry%original = "500"
            entry%value = repr(vc_log_show_limit)
            entry%doc = "Limit the number of items shown by the VC log commands."//LF// &
                        "Zero means unlimited."//LF// &
                        "Not all VC backends are able to support this feature."
        case ("vc_logentry_check_hook")
            entry%file = "vc_dispatcher_fm.f90"
            entry%fortran = "vc_logentry_check_hook"
            entry%doc = "Normal hook run by `vc_finish_logentry'."//LF// &
                        "Use this to impose your own rules on the entry in addition to any the"//LF// &
                        "dispatcher client wants to enforce."
        case ("vc_make_backup_files")
            entry%file = "vc_hooks_fm.f90"
            entry%fortran = "vc_make_backup_files"
            entry%user_option = .true.
            entry%original = ".false."
            entry%value = repr(vc_make_backup_files)
            entry%doc = "If true, backups of registered files are made as with other files."//LF// &
                        "If false (the default), files covered by version control don't get backups."
        case ("vc_prefix_map")
            entry%file = "vc_hooks_fm.f90"
            entry%fortran = "vc_prefix_map"
            entry%doc = "Version control prefix map (C-x v)."
        case ("vc_register_switches")
            entry%file = "vc_fm.f90"
            entry%fortran = "vc_register_switches"
            entry%user_option = .true.
            entry%doc = "A string or list of strings; extra switches for registering a file."//LF// &
                        "These are passed to the checkin program by `vc_register'."
        case ("vc_resolve_conflicts")
            entry%file = "vc_hooks_fm.f90"
            entry%fortran = "vc_resolve_conflicts"
            entry%user_option = .true.
            entry%original = ".true."
            entry%value = repr(vc_resolve_conflicts)
            entry%doc = "Whether to mark conflicted file as resolved upon saving."//LF// &
                        ""//LF// &
                        "If this is true and there are no more conflict markers in the file,"//LF// &
                        "VC will mark the conflicts in the saved file as resolved.  This is"//LF// &
                        "only meaningful for VCS that handle conflicts by inserting conflict"//LF// &
                        "markers in a conflicted file."//LF// &
                        ""//LF// &
                        "When saving a conflicted file, VC first tries to use the value"//LF// &
                        "of `vc_BACKEND_resolve_conflicts', for handling backend-specific"//LF// &
                        "settings.  It defaults to this option if that option has the special"//LF// &
                        "value `default'."
        case ("vc_revert_show_diff")
            entry%file = "vc_fm.f90"
            entry%fortran = "vc_revert_show_diff"
            entry%user_option = .true.
            entry%original = "VC_REVERT_SHOW_DIFF_T"

            select case (vc_revert_show_diff)
            case (VC_REVERT_SHOW_DIFF_NIL)
                entry%value = "VC_REVERT_SHOW_DIFF_NIL"
            case (VC_REVERT_SHOW_DIFF_T)
                entry%value = "VC_REVERT_SHOW_DIFF_T"
            case (VC_REVERT_SHOW_DIFF_KILL)
                entry%value = "VC_REVERT_SHOW_DIFF_KILL"
            case default
                entry%value = repr(vc_revert_show_diff)
            end select

            entry%doc = "If true, `vc_revert' shows a `vc_diff' buffer before querying."//LF// &
                        "VC_REVERT_SHOW_DIFF_T shows it and buries it afterwards,"//LF// &
                        "VC_REVERT_SHOW_DIFF_KILL shows it and kills it afterwards, and"//LF// &
                        "VC_REVERT_SHOW_DIFF_NIL doesn't show it."
        case ("vc_sentinel_movepoint")
            entry%file = "vc_dispatcher_fm.f90"
            entry%fortran = "vc_sentinel_movepoint"
            entry%original = "0"
            entry%value = repr(vc_sentinel_movepoint)
            entry%doc = "Where a sentinel wants point to go afterwards (0 for nil)."
        case ("vc_state_base")
            entry%file = "vc_hooks_fm.f90"
            entry%fortran = "vc_state_base"
            entry%doc = "Base face for VC state indicator."
        case ("vc_suppress_confirm")
            entry%file = "vc_dispatcher_fm.f90"
            entry%fortran = "vc_suppress_confirm"
            entry%user_option = .true.
            entry%original = ".false."
            entry%value = repr(vc_suppress_confirm)
            entry%doc = "If true, treat user as expert; suppress yes-no prompts on some things."
        case ("vc_use_short_revision")
            entry%file = "vc_hooks_fm.f90"
            entry%fortran = "vc_use_short_revision"
            entry%original = ".false."
            entry%value = repr(vc_use_short_revision)
            entry%doc = "If true, VC backend functions should return short revisions if possible."//LF// &
                        "This is set to true when calling `vc_short_revision', which will"//LF// &
                        "then call the `working_revision' backend function."
        case ("view_exits_all_viewing_windows")
            entry%file = "view_fm.f90"
            entry%fortran = "view_exits_all_viewing_windows"
            entry%user_option = .true.
            entry%original = ".false."
            entry%value = repr(view_exits_all_viewing_windows)
            entry%doc = "True means restore all windows used to view buffer."//LF// &
                        "Commands that restore windows when finished viewing a buffer,"//LF// &
                        "apply to all windows that display the buffer and have restore"//LF// &
                        "information.  If `view_exits_all_viewing_windows' is false, only"//LF// &
                        "the selected window is considered for restoring."
        case ("view_inhibit_help_message")
            entry%file = "view_fm.f90"
            entry%fortran = "view_inhibit_help_message"
            entry%user_option = .true.
            entry%original = ".false."
            entry%value = repr(view_inhibit_help_message)
            entry%doc = "True inhibits the help message shown upon entering View mode."//LF// &
                        "This setting takes effect only when View mode is entered via an"//LF// &
                        "interactive command; otherwise the help message is not shown."
        case ("view_mode_hook")
            entry%file = "view_fm.f90"
            entry%fortran = "view_mode_hook"
            entry%user_option = .true.
            entry%doc = "Normal hook run when starting to view a buffer or file."
        case ("view_mode_map")
            entry%file = "view_fm.f90"
            entry%fortran = "view_mode_map"
            entry%doc = "Keymap for `view_mode'."
        case ("view_no_disable_on_exit")
            entry%file = "view_fm.f90"
            entry%fortran = "view_no_disable_on_exit"
            entry%original = ".false."
            entry%value = repr(view_no_disable_on_exit)
            entry%doc = "If true, View mode ""exit"" commands don't actually disable View mode."//LF// &
                        "Instead, these commands just switch buffers or windows."//LF// &
                        "This is set in certain buffers by specialized features such as help commands"//LF// &
                        "that use View mode automatically."
        case ("view_read_only")
            entry%file = "files_fm.f90"
            entry%fortran = "view_read_only"
            entry%user_option = .true.
            entry%original = ".false."
            entry%value = repr(view_read_only)
            entry%doc = "True means buffers visiting files read-only do so in view mode."//LF// &
                        "In fact, this means that all read-only buffers normally have"//LF// &
                        "View mode enabled, including buffers that are read-only because"//LF// &
                        "you visit a file you cannot alter, and buffers you make read-only"//LF// &
                        "using \[read_only_mode]."
        case ("view_scroll_auto_exit")
            entry%file = "view_fm.f90"
            entry%fortran = "view_scroll_auto_exit"
            entry%user_option = .true.
            entry%original = ".false."
            entry%value = repr(view_scroll_auto_exit)
            entry%doc = "True means scrolling past the end of buffer exits View mode."//LF// &
                        "False means attempting to scroll past the end of the buffer,"//LF// &
                        "only rings the bell and gives a message on how to leave."
        case ("visible_bell")
            entry%file = "term_fm.f90"
            entry%fortran = "visible_bell"
            entry%user_option = .true.
            entry%original = ".false."
            entry%value = repr(visible_bell)
            entry%doc = "True means try to flash the frame to represent a bell."//LF// &
                        ""//LF// &
                        "See also `ring_bell_function'."
        case ("window_min_height")
            entry%file = "window_fm.f90"
            entry%fortran = "window_min_height"
            entry%user_option = .true.
            entry%original = "4"
            entry%value = repr(window_min_height)
            entry%doc = "The minimum total height, in lines, of any window."//LF// &
                        "The value has to accommodate one text line, a mode and header line,"//LF// &
                        "a horizontal scroll bar and a bottom divider, if present.  A value"//LF// &
                        "less than `window_safe_min_height' is ignored."
        case ("window_min_width")
            entry%file = "window_fm.f90"
            entry%fortran = "window_min_width"
            entry%user_option = .true.
            entry%original = "10"
            entry%value = repr(window_min_width)
            entry%doc = "The minimum total width, in columns, of any window."//LF// &
                        "The value has to accommodate two text columns as well as margins,"//LF// &
                        "fringes, a scroll bar and a right divider, if present.  A value less"//LF// &
                        "than `window_safe_min_width' is ignored."
        case ("words_include_escapes")
            entry%file = "syntax_fm.f90"
            entry%fortran = "words_include_escapes"
            entry%user_option = .true.
            entry%original = ".false."
            entry%value = repr(words_include_escapes)
            entry%doc = "True means `forward_word', etc., should treat escape chars part of words."
        case ("xargs_program")
            entry%file = "grep_fm.f90"
            entry%fortran = "xargs_program"

            if (allocated(xargs_program)) then
                entry%value = repr(xargs_program)
            else
                entry%value = "unallocated"
            end if

            entry%doc = "The default xargs program for `grep_find_command'."//LF// &
                        "See `grep_find_use_xargs'."//LF// &
                        "This variable's value takes effect when `grep_compute_defaults' is"//LF// &
                        "called."
        case ("y_or_n_p_history_variable")
            entry%file = "subr_fm.f90"
            entry%fortran = "y_or_n_p_history_variable"

            if (allocated(y_or_n_p_history_variable)) then
                entry%value = repr(y_or_n_p_history_variable)
            else
                entry%value = "unallocated"
            end if

            entry%doc = "Name of the history list to add `y_or_n_p' answers to (unallocated for"//LF// &
                        "no history)."
        case ("y_or_n_p_use_read_key")
            entry%file = "subr_fm.f90"
            entry%fortran = "y_or_n_p_use_read_key"
            entry%original = ".false."
            entry%value = repr(y_or_n_p_use_read_key)
            entry%doc = "Use `read_key' when reading answers to ""y or n"" questions by `y_or_n_p'."//LF// &
                        "Otherwise, use the `read_from_minibuffer' to read the answers."//LF// &
                        ""//LF// &
                        "When reading via the minibuffer, you can use the normal commands"//LF// &
                        "available in the minibuffer, and can, for instance, temporarily"//LF// &
                        "switch to another buffer, do things there, and then switch back"//LF// &
                        "to the minibuffer before entering the character.  This is not"//LF// &
                        "possible when using `read_key', but using `read_key' may be less"//LF// &
                        "confusing to some users."
        case ("yes_or_no_prompt")
            entry%file = "fns_fm.f90"
            entry%fortran = "yes_or_no_prompt"
            entry%user_option = .true.

            if (allocated(yes_or_no_prompt)) then
                entry%value = repr(yes_or_no_prompt)
            else
                entry%value = "unallocated"
            end if

            entry%doc = "String to append when `yes_or_no_p' asks a question."//LF// &
                        "For best results this should end in a space."
        case default
            found = .false.
        end select
    end subroutine variable_doc

    !> The kind of value the user option called `name` takes (OPTION_NONE
    !> if `set_variable` cannot set it, or for an unknown name), and
    !> whether it is a setting object, which can have buffer-local values.
    subroutine user_option_info(name, kind, setting)
        character(len=*), intent(in) :: name
        integer, intent(out) :: kind
        logical, intent(out) :: setting

        kind = OPTION_NONE
        setting = .false.

        select case (name)
        case ("abbrev_all_caps")
            kind = OPTION_LOGICAL
            setting = .true.
        case ("abbrev_file_name")
            kind = OPTION_STRING
        case ("abbrev_mode")
            kind = OPTION_LOGICAL
            setting = .true.
        case ("adaptive_fill_first_line_regexp")
            kind = OPTION_STRING
        case ("adaptive_fill_mode")
            kind = OPTION_LOGICAL
            setting = .true.
        case ("adaptive_fill_regexp")
            kind = OPTION_STRING
        case ("ansi_color_bold_is_bright")
            kind = OPTION_LOGICAL
            setting = .true.
        case ("ansi_color_for_comint_mode")
            kind = OPTION_CHOICE
            setting = .true.
        case ("ansi_color_for_compilation_mode")
            kind = OPTION_CHOICE
            setting = .true.
        case ("async_shell_command_buffer")
            kind = OPTION_CHOICE
            setting = .true.
        case ("async_shell_command_display_buffer")
            kind = OPTION_LOGICAL
            setting = .true.
        case ("async_shell_command_width")
            kind = OPTION_INTEGER
            setting = .true.
        case ("auto_fill_inhibit_regexp")
            kind = OPTION_STRING
            setting = .true.
        case ("auto_revert_avoid_polling")
            kind = OPTION_LOGICAL
        case ("auto_revert_check_vc_info")
            kind = OPTION_LOGICAL
        case ("auto_revert_interval")
            kind = OPTION_REAL
        case ("auto_revert_mode_text")
            kind = OPTION_STRING
        case ("auto_revert_notify_exclude_dir_regexp")
            kind = OPTION_STRING
        case ("auto_revert_remote_files")
